import{_ as r,o as l,c as o,ae as t}from"./chunks/framework.RRduUuAx.js";const q=JSON.parse('{"title":"よくある質問（FAQ）","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ja/faq/index.md","filePath":"v1/ja/faq/index.md"}'),i={name:"v1/ja/faq/index.md"};function e(n,a,s,h,d,g){return l(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="よくある質問-faq" tabindex="-1">よくある質問（FAQ） <a class="header-anchor" href="#よくある質問-faq" aria-label="Permalink to &quot;よくある質問（FAQ）&quot;">​</a></h1><p>このページでは、コアラ家計簿の利用中によくある質問と対処方法をまとめています。トラブル時はまずこちらをご確認ください。</p><hr><h2 id="明細インポート" tabindex="-1">明細インポート <a class="header-anchor" href="#明細インポート" aria-label="Permalink to &quot;明細インポート&quot;">​</a></h2><h3 id="q-どの明細ソースに対応していますか-対応ファイル形式は" tabindex="-1">Q：どの明細ソースに対応していますか？対応ファイル形式は？ <a class="header-anchor" href="#q-どの明細ソースに対応していますか-対応ファイル形式は" aria-label="Permalink to &quot;Q：どの明細ソースに対応していますか？対応ファイル形式は？&quot;">​</a></h3><p><strong>A：</strong> 現在、5 つのソースに対応しています。</p><ul><li><strong>テンプレート</strong>：CSV（<code>.csv</code>）</li><li><strong>WeChat</strong>：CSV / Excel（<code>.csv</code> / <code>.xlsx</code> / <code>.xls</code>）</li><li><strong>Alipay</strong>：CSV（<code>.csv</code>）</li><li><strong>Pixiu</strong>：CSV（<code>.csv</code>）</li><li><strong>iCost</strong>：Excel（<code>.xlsx</code> / <code>.xls</code>）— iCost の CSV は非対応</li></ul><p>関連ガイド：</p><ul><li><a href="./../guide/01-template-bill-import-guide">テンプレート明細インポート（CSV）</a></li><li><a href="./../guide/02-wechat-bill-import-guide">WeChat 明細インポート</a></li><li><a href="./../guide/03-alipay-bill-import-guide">Alipay 明細インポート</a></li><li><a href="./../guide/07-pixiu-bill-import-guide">Pixiu 明細インポート</a></li><li><a href="./../guide/08-icost-bill-import-guide">iCost 明細インポート</a></li></ul><h3 id="q-「解析に失敗しました-開けません-ヘッダーが見つかりません」と出ます" tabindex="-1">Q：「解析に失敗しました／開けません／ヘッダーが見つかりません」と出ます <a class="header-anchor" href="#q-「解析に失敗しました-開けません-ヘッダーが見つかりません」と出ます" aria-label="Permalink to &quot;Q：「解析に失敗しました／開けません／ヘッダーが見つかりません」と出ます&quot;">​</a></h3><p><strong>A：</strong> 多くは次のいずれかです（よくある順）。</p><ol><li><strong>インポート元の選択が違う</strong>：例えば WeChat のファイルをテンプレート/Alipay として解析すると失敗したり項目がずれたりします。</li><li><strong>ファイルを編集してしまった</strong>：Excel/WPS で開いて表頭を変更、列の削除/追加、区切り文字変更などをすると解析に失敗しやすくなります。</li><li><strong>対応していない形式</strong>：例えば iCost を CSV で出力した、Alipay の非標準形式を使った、など。</li><li><strong>ファイルが破損している</strong>：ダウンロード途中で切れた、添付が壊れている、共有時に欠けた、など。</li><li><strong>ファイルが大きすぎる</strong>：処理が遅くなったり失敗することがあります。期間を分けて書き出し、分割して取り込むのがおすすめです。</li></ol><p>おすすめ：元アプリから「未編集の状態」で再エクスポートし、コアラ家計簿側のインポート元を正しく選択してから再度解析してください。</p><h3 id="q-取り込み後の金額が-0-になった-金額が合いません" tabindex="-1">Q：取り込み後の金額が 0 になった／金額が合いません <a class="header-anchor" href="#q-取り込み後の金額が-0-になった-金額が合いません" aria-label="Permalink to &quot;Q：取り込み後の金額が 0 になった／金額が合いません&quot;">​</a></h3><p><strong>A：</strong> よくある原因は以下です。</p><ul><li><strong>収入/支出の判定が崩れている</strong>：ソースによっては「收入/支出」のキーワードで参照する金額列が決まります（例：Pixiu の流入/流出）。種別列が想定外だと読み取りがずれることがあります。</li><li><strong>金額欄が空／不正文字が混ざっている</strong>：余計なスペースや見えない文字が原因になる場合があります。</li><li><strong>千区切り／符号</strong>：<code>+/-</code> や千区切りが含まれていても通常は対応しますが、編集・再保存で形式が崩れると失敗することがあります。</li></ul><p>対処：プレビュー画面で <strong>収支種別</strong> と <strong>金額</strong> を優先して確認してください。おかしい場合は元ファイルを再エクスポートするのが確実です。</p><h3 id="q-カテゴリ-口座-タグが期待通りに一致しません" tabindex="-1">Q：カテゴリ／口座／タグが期待通りに一致しません <a class="header-anchor" href="#q-カテゴリ-口座-タグが期待通りに一致しません" aria-label="Permalink to &quot;Q：カテゴリ／口座／タグが期待通りに一致しません&quot;">​</a></h3><p><strong>A：</strong> できるだけ自動一致を試みますが、アプリごとに分類体系が違うため、完全一致は保証できません。</p><ul><li><strong>カテゴリ</strong>：プレビューで 1 件ずつ修正できます。より一致しやすくするには、コアラ家計簿側にエクスポートと同名のカテゴリを事前に作成してから再解析してください。</li><li><strong>口座</strong>：口座名や支払方法で照合します。見つからない場合は新規口座が作成されることがあります。よく使う口座を先に作っておき、プレビューでまとめて修正するのがおすすめです。</li><li><strong>タグ</strong>：タグ名で照合します。存在しないタグは作成されることがあります。不要なタグ名（余計な空白や記号）になっていないか確認してください。</li></ul><h3 id="q-重複-同じ明細の二重取り込み-を自動で防げますか" tabindex="-1">Q：重複（同じ明細の二重取り込み）を自動で防げますか？ <a class="header-anchor" href="#q-重複-同じ明細の二重取り込み-を自動で防げますか" aria-label="Permalink to &quot;Q：重複（同じ明細の二重取り込み）を自動で防げますか？&quot;">​</a></h3><p><strong>A：</strong> ソースによって挙動は異なりますが、基本は <strong>自動で完全な重複排除はしない</strong> 前提でご利用ください。</p><ul><li>おすすめ：同じファイル/同じ期間を繰り返し取り込まない。分割する場合は期間が重ならないようにする。</li><li>すでに重複した場合：明細一覧で期間を絞り込み、手動で削除してください。</li></ul><h3 id="q-返金-振替-红包などの特殊な取引はどう扱われますか" tabindex="-1">Q：返金／振替／红包などの特殊な取引はどう扱われますか？ <a class="header-anchor" href="#q-返金-振替-红包などの特殊な取引はどう扱われますか" aria-label="Permalink to &quot;Q：返金／振替／红包などの特殊な取引はどう扱われますか？&quot;">​</a></h3><p><strong>A：</strong> プラットフォームごとの書き出し項目が大きく異なるため、取り込み後は次をおすすめします。</p><ul><li>プレビューで <strong>収支種別</strong> と <strong>金額の正負</strong> を確認</li><li>必要ならカテゴリを手動調整（例：返金を「返金/その他収入」へ）</li><li>取引状態や注文番号などはメモに追記されることが多く、後から参照しやすくなります</li></ul><h3 id="q-一度にどのくらい取り込むのが良いですか-遅いです" tabindex="-1">Q：一度にどのくらい取り込むのが良いですか？遅いです <a class="header-anchor" href="#q-一度にどのくらい取り込むのが良いですか-遅いです" aria-label="Permalink to &quot;Q：一度にどのくらい取り込むのが良いですか？遅いです&quot;">​</a></h3><p><strong>A：</strong> 期間で分割するのがおすすめです。</p><ul><li>WeChat/Alipay は <strong>3 か月以内</strong>で書き出すと安定しやすく、解析も速くなります</li><li>大量データは複数ファイルに分けて順番に取り込み</li><li>取り込み中はアプリを前面にしておくと中断しにくくなります</li></ul><hr><h2 id="複数帳本-マルチ-ledger" tabindex="-1">複数帳本（マルチ Ledger） <a class="header-anchor" href="#複数帳本-マルチ-ledger" aria-label="Permalink to &quot;複数帳本（マルチ Ledger）&quot;">​</a></h2><h3 id="q-帳本を切り替えたらデータが「消えた」ように見えます" tabindex="-1">Q：帳本を切り替えたらデータが「消えた」ように見えます <a class="header-anchor" href="#q-帳本を切り替えたらデータが「消えた」ように見えます" aria-label="Permalink to &quot;Q：帳本を切り替えたらデータが「消えた」ように見えます&quot;">​</a></h3><p><strong>A：</strong> 別の帳本に切り替わっている可能性が高いです。明細・カテゴリ・タグ・統計は帳本ごとに分かれています。</p><p>対処：<strong>帳本管理</strong>で現在の帳本を確認してから、明細一覧をご確認ください。</p><h3 id="q-帳本ごとに分かれるもの-共通のものは" tabindex="-1">Q：帳本ごとに分かれるもの／共通のものは？ <a class="header-anchor" href="#q-帳本ごとに分かれるもの-共通のものは" aria-label="Permalink to &quot;Q：帳本ごとに分かれるもの／共通のものは？&quot;">​</a></h3><p><strong>A：</strong></p><ul><li><strong>帳本ごと</strong>：明細、カテゴリ、タグ、統計</li><li><strong>端末で共通</strong>：口座（複数帳本で同じ口座を利用できます）</li></ul><h3 id="q-帳本を削除するとどうなりますか-復元できますか" tabindex="-1">Q：帳本を削除するとどうなりますか？復元できますか？ <a class="header-anchor" href="#q-帳本を削除するとどうなりますか-復元できますか" aria-label="Permalink to &quot;Q：帳本を削除するとどうなりますか？復元できますか？&quot;">​</a></h3><p><strong>A：</strong> 削除すると、その帳本は端末から削除されます。クラウド同期を利用している場合は、同期後にクラウド側にも削除が反映されます。アプリ内で復元できないため、削除前に必ずご確認ください。</p><hr><h2 id="通貨と為替レート" tabindex="-1">通貨と為替レート <a class="header-anchor" href="#通貨と為替レート" aria-label="Permalink to &quot;通貨と為替レート&quot;">​</a></h2><h3 id="q-基軸通貨-帳本通貨-とは-何に影響しますか" tabindex="-1">Q：基軸通貨（帳本通貨）とは？何に影響しますか？ <a class="header-anchor" href="#q-基軸通貨-帳本通貨-とは-何に影響しますか" aria-label="Permalink to &quot;Q：基軸通貨（帳本通貨）とは？何に影響しますか？&quot;">​</a></h3><p><strong>A：</strong> 基軸通貨（帳本通貨）は、現在の帳本で「主に表示する通貨」です。主に次に影響します。</p><ul><li>金額表示（換算表示）</li><li>概覧/統計の計算</li><li>為替一覧（基軸通貨に対するレート表示）</li></ul><h3 id="q-レート更新後に過去の明細の換算表示が変わりました" tabindex="-1">Q：レート更新後に過去の明細の換算表示が変わりました <a class="header-anchor" href="#q-レート更新後に過去の明細の換算表示が変わりました" aria-label="Permalink to &quot;Q：レート更新後に過去の明細の換算表示が変わりました&quot;">​</a></h3><p><strong>A：</strong> 換算表示は <strong>現在の為替レート</strong> を使います。レート更新や基軸通貨の変更後、過去明細の「換算表示」は変わることがありますが、<strong>元の取引金額</strong>は変わりません。</p><h3 id="q-オフライン時はどうなりますか-更新に失敗します" tabindex="-1">Q：オフライン時はどうなりますか？更新に失敗します <a class="header-anchor" href="#q-オフライン時はどうなりますか-更新に失敗します" aria-label="Permalink to &quot;Q：オフライン時はどうなりますか？更新に失敗します&quot;">​</a></h3><p><strong>A：</strong> オフライン時は、保存済みのレートをできるだけ利用します。更新に失敗する場合は：</p><ol><li>ネットワークを確認</li><li>少し時間を置いて再更新</li><li>手動でレートを変更している場合は、その値が意図通りか確認</li></ol><hr><h2 id="クラウドバックアップと同期" tabindex="-1">クラウドバックアップと同期 <a class="header-anchor" href="#クラウドバックアップと同期" aria-label="Permalink to &quot;クラウドバックアップと同期&quot;">​</a></h2><h3 id="q-クラウドバックアップにログインは必要ですか" tabindex="-1">Q：クラウドバックアップにログインは必要ですか？ <a class="header-anchor" href="#q-クラウドバックアップにログインは必要ですか" aria-label="Permalink to &quot;Q：クラウドバックアップにログインは必要ですか？&quot;">​</a></h3><p><strong>A：</strong> 必要です。現在は <strong>Apple でのログイン</strong>に対応しています。設定画面上部のユーザーカードからログインできます。</p><h3 id="q-同期されるもの-されないものは" tabindex="-1">Q：同期されるもの／されないものは？ <a class="header-anchor" href="#q-同期されるもの-されないものは" aria-label="Permalink to &quot;Q：同期されるもの／されないものは？&quot;">​</a></h3><p><strong>A：</strong></p><ul><li><strong>同期される</strong>：帳本、明細、口座、カテゴリ、タグ</li><li><strong>同期されない</strong>：アプリ設定（テーマ/言語など）、キャッシュ、個人設定</li></ul><h3 id="q-自動同期のタイミングは-手動同期は" tabindex="-1">Q：自動同期のタイミングは？手動同期は？ <a class="header-anchor" href="#q-自動同期のタイミングは-手動同期は" aria-label="Permalink to &quot;Q：自動同期のタイミングは？手動同期は？&quot;">​</a></h3><p><strong>A：</strong></p><ul><li><strong>自動</strong>：アプリ起動時、データ変更後、帳本切り替え時など</li><li><strong>手動</strong>：設定画面右上の雲アイコンをタップ</li></ul><p>手動同期中は、完了までアプリを前面にしておいてください。</p><h3 id="q-複数端末で同じデータを編集した場合は" tabindex="-1">Q：複数端末で同じデータを編集した場合は？ <a class="header-anchor" href="#q-複数端末で同じデータを編集した場合は" aria-label="Permalink to &quot;Q：複数端末で同じデータを編集した場合は？&quot;">​</a></h3><p><strong>A：</strong> コアラ家計簿はできるだけ最新の変更を優先しつつ、まだ同期されていない端末側の変更が上書きされないようにします。複数端末で使う場合は、片方の端末で同期を完了してからもう一方で編集するのがおすすめです。</p><h3 id="q-再インストール-機種変更後に復元できますか" tabindex="-1">Q：再インストール／機種変更後に復元できますか？ <a class="header-anchor" href="#q-再インストール-機種変更後に復元できますか" aria-label="Permalink to &quot;Q：再インストール／機種変更後に復元できますか？&quot;">​</a></h3><p><strong>A：</strong></p><ul><li><strong>ログイン済みで同期済み</strong>：再インストール後に同じアカウントでログインし、同期が終わるのを待てば復元できます</li><li><strong>未ログイン</strong>：データは端末内のみのため、アンインストールすると復元できません</li></ul><hr><h2 id="メンバーシップと料金" tabindex="-1">メンバーシップと料金 <a class="header-anchor" href="#メンバーシップと料金" aria-label="Permalink to &quot;メンバーシップと料金&quot;">​</a></h2><h3 id="q-なぜ買い切り-一次購入-にしないのですか" tabindex="-1">Q：なぜ買い切り（一次購入）にしないのですか？ <a class="header-anchor" href="#q-なぜ買い切り-一次購入-にしないのですか" aria-label="Permalink to &quot;Q：なぜ買い切り（一次購入）にしないのですか？&quot;">​</a></h3><p><strong>A：</strong> コアラ家計簿を「一度きりの取引」ではなく、長期で継続的に改善していくプロダクトにしたいからです。</p><p>メンバーシップ制にすることで、継続的な不具合修正や体験の改善、OS アップデートや新機種への対応に安定して取り組めます。また、同期・データ安全性・パフォーマンスなど、長期的な投資が必要な機能も継続して強化できます。結果として、買い切り後に更新が止まってしまうリスクを減らし、使うほど良くなるアプリを提供できます。</p><hr><h2 id="フィードバックとサポート" tabindex="-1">フィードバックとサポート <a class="header-anchor" href="#フィードバックとサポート" aria-label="Permalink to &quot;フィードバックとサポート&quot;">​</a></h2><h3 id="q-問い合わせ時に何を伝えると早く解決できますか" tabindex="-1">Q：問い合わせ時に何を伝えると早く解決できますか？ <a class="header-anchor" href="#q-問い合わせ時に何を伝えると早く解決できますか" aria-label="Permalink to &quot;Q：問い合わせ時に何を伝えると早く解決できますか？&quot;">​</a></h3><p><strong>A：</strong> 次の情報があると切り分けが早くなります。</p><ul><li>インポート元（WeChat/Alipay/Pixiu/iCost/テンプレート）</li><li>ファイル形式（CSV/Excel）と書き出し期間</li><li>エラー表示のスクリーンショット（あれば）</li><li>試したこと（再エクスポート、ソース変更、別ファイルで試した等）</li></ul>',75)])])}const c=r(i,[["render",e]]);export{q as __pageData,c as default};
